NODE_PATH=$(npm root -g) node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Check variants_json on the product itself
const product = db.prepare(\"SELECT variants_json FROM products WHERE product_id='PROD-F9994E'\").get();
console.log('variants_json:', product.variants_json);

// Check if there's another variants table
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all();
console.log('\nAll tables:', tables.map(t => t.name));

// Look for any table that might have PROD-F9994E
for (const t of tables) {
  try {
    const rows = db.prepare('SELECT * FROM ' + t.name + ' LIMIT 0').all();
    const cols = db.prepare('PRAGMA table_info(' + t.name + ')').all().map(c => c.name);
    if (cols.some(c => c.includes('product') || c.includes('variant') || c.includes('item'))) {
      const count = db.prepare('SELECT COUNT(*) as cnt FROM ' + t.name).get();
      console.log(t.name + ' (' + count.cnt + ' rows) cols:', cols.join(', '));
    }
  } catch(e) {}
}

// Check ss_variants or similar
try {
  const ssv = db.prepare(\"SELECT * FROM ss_variants WHERE product_id='PROD-F9994E'\").all();
  console.log('\nss_variants for PROD-F9994E:', ssv.length, 'rows');
  ssv.forEach(v => console.log(JSON.stringify(v)));
} catch(e) { console.log('No ss_variants table'); }
db.close();
"

NODE_PATH=$(npm root -g) node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Check if there are ANY rt_variants for state-shopping products
const stateProducts = db.prepare(\"SELECT product_id FROM products WHERE source_skill='state-shopping'\").all();
console.log('state-shopping products count:', stateProducts.length);

// Check rt_variants for a few state-shopping products
for (const p of stateProducts.slice(0, 3)) {
  const cnt = db.prepare('SELECT COUNT(*) as c FROM rt_variants WHERE product_id=?').get(p.product_id);
  console.log(p.product_id, '-> rt_variants:', cnt.c);
}

// Check tau2Retail products
const rtProducts = db.prepare(\"SELECT product_id, name FROM products WHERE source_skill='tau2Retail'\").all();
console.log('\ntau2Retail products count:', rtProducts.length);
rtProducts.slice(0, 3).forEach(p => {
  const cnt = db.prepare('SELECT COUNT(*) as c FROM rt_variants WHERE product_id=?').get(p.product_id);
  console.log(p.product_id, p.name, '-> rt_variants:', cnt.c);
});

// Check if PROD-F9994E has data in cart_items
const cartItems = db.prepare(\"SELECT * FROM cart_items WHERE product_id='PROD-F9994E'\").all();
console.log('\ncart_items for PROD-F9994E:', cartItems);

// Check order_items
const orderItems = db.prepare(\"SELECT * FROM order_items WHERE product_id='PROD-F9994E'\").all();
console.log('order_items for PROD-F9994E:', orderItems.length);
orderItems.forEach(oi => console.log(JSON.stringify(oi)));

// Look at variants_json for nearby state-shopping products that DO have variants
const withVariants = db.prepare(\"SELECT product_id, name, variants_json FROM products WHERE source_skill='state-shopping' AND variants_json != '[]' LIMIT 3\").all();
console.log('\nstate-shopping products with variants_json:');
withVariants.forEach(p => console.log(p.product_id, p.name, p.variants_json?.substring(0, 200)));
db.close();
"

