cartItems.forEach(ci => console.log(JSON.stringify(ci)));

// Check the users with this in their cart
for (const ci of cartItems) {
  const user = db.prepare('SELECT user_id, name, email FROM users WHERE user_id=?').get(ci.customer_id);
  console.log('\nUser:', JSON.stringify(user));

  // Check their orders
