NODE_PATH=$(npm root -g) node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Find orders containing Harbor Cotton Crew Tee or similar items in order_items
const harborOrders = db.prepare(\"SELECT oi.*, o.status, o.customer_id, o.total_paid FROM order_items oi JOIN orders o ON oi.order_id = o.order_id WHERE oi.name LIKE '%Harbor%' OR oi.name LIKE '%Cotton Crew%' OR oi.product_id = 'PROD-F9994E'\").all();
console.log('Orders with Harbor Cotton Crew Tee:', harborOrders);

// Look for any delivered orders that contain clothing items that could be exchanged for the Harbor Tee
// The exchange policy says same product type - so look for clothing/tee items
const clothingOrders = db.prepare(\"SELECT oi.*, o.status, o.customer_id FROM order_items oi JOIN orders o ON oi.order_id = o.order_id WHERE o.status = 'delivered' AND (oi.name LIKE '%Tee%' OR oi.name LIKE '%Shirt%' OR oi.name LIKE '%shirt%' OR oi.name LIKE '%tee%')\").all();
console.log('\nDelivered orders with Tee/Shirt items:');
clothingOrders.forEach(o => console.log(JSON.stringify(o)));

// Also check the tau2Retail order #W7231611
const tauOrder = db.prepare(\"SELECT * FROM orders WHERE order_id='#W7231611'\").get();
console.log('\ntau2 order #W7231611:', JSON.stringify(tauOrder, null, 2));
db.close();
"

